-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras (Trasy) — 24 tras
-- Vygenerováno pro Velín → Trasy. NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy se vkládají jako is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže podle (name, branch_id), aby šlo migraci pustit opakovaně.
-- ════════════════════════════════════════════════════════════════════
do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první pobočka.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Hrady a zámky jižní Vysočiny  (010_hrady.json)
  delete from public.routes where name = 'Hrady a zámky jižní Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Hrady a zámky jižní Vysočiny', 'Okruh po nejkrásnějších hradech a zámcích jižní Vysočiny vede převážně po klidných silnicích II. a III. třídy s příjemným střídáním lesních úseků, rybníků a rozhlédnutých plání Českomoravské vrchoviny. Trasa nabízí svižné zatáčky kolem Kamene a Roštejna i pohodovější přejezdy mezi historickými městečky Žirovnice, Kamenice nad Lipou a Telč. Vrcholem je zastávka v UNESCO městě Telč s renesančním zámkem a náměstím. Nejlepší je jaro až podzim; pozor na úzké a místy hrbolaté lesní silnice u Roštejna a na turistický provoz v Telči za slunečných víkendů.', 'loop', 175, 225, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.424, "lng": 15.015, "label": "Hrad Kámen"}, {"lat": 49.30264, "lng": 15.0793, "label": "Zámek Kamenice nad Lipou"}, {"lat": 49.254, "lng": 15.185, "label": "Zámek Žirovnice"}, {"lat": 49.183, "lng": 15.455, "label": "Zámek Telč"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.424,15.015%7C49.30264,15.0793%7C49.254,15.185%7C49.183,15.455%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_a_l%C3%ADpa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDirovnice%20z%C3%A1mek%20zdola.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Tel%C4%8D_kaple_V%C5%A1ech_svat%C3%BDch.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn_hrad_03.JPG"}'::text[], '{"Hrad Kámen","Zámek Kamenice nad Lipou","Zámek Žirovnice","Zámek Telč","Hrad Roštejn"}'::text[], false, 10, 'approved');

  -- Za rozhlednami Vysočiny  (020_rozhledny.json)
  delete from public.routes where name = 'Za rozhlednami Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Za rozhlednami Vysočiny', 'Kompaktní vyhlídkový okruh po malebných silnicích druhé a třetí třídy kolem Pelhřimova a Pacova, který se ZÁMĚRNĚ vyhýbá dálnicím i rychlostním silnicím a drží se klidných okresek přes lesy a pahorkatinu Vysočiny. Trasa nabízí táhlé zatáčky, střídání stoupání a sjezdů a otevřené výhledy z hřebenů Křemešnické vrchoviny, nejlepší je od května do října, kdy jsou rozhledny přístupné a vozovka suchá. Pozor na úzké lesní úseky, občasný štěrk a listí v zatáčkách, v obcích na cyklisty a zemědělskou techniku. Povrch je vesměs slušný, ale místy hrbolatý, proto volte plynulou jízdu. Okruh začíná i končí v Mezné u Pelhřimova.', 'loop', 118, 195, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.431, "lng": 15.223, "label": "Pelhřimov – Masarykovo náměstí"}, {"lat": 49.4035, "lng": 15.32711, "label": "Rozhledna Pípalka na Křemešníku"}, {"lat": 49.376, "lng": 15.435, "label": "Čeřínek – Přední skála"}, {"lat": 49.53578, "lng": 15.00367, "label": "Strážiště u Pacova"}, {"lat": 49.42439, "lng": 15.01388, "label": "Hrad Kámen"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.431,15.223%7C49.4035,15.32711%7C49.376,15.435%7C49.53578,15.00367%7C49.42439,15.01388', 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skl%C3%A1dan%C3%A1%20sk%C3%A1la.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kaple%20svat%C3%A9ho%20Jana%20K%C5%99titele%20pod%20Str%C3%A1%C5%BEi%C5%A1t%C4%9Bm%20(Q67180794)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C3%A1men.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG"}'::text[], '{"Rozhledna Pípalka na Křemešníku","Čeřínek – Přední skála","Strážiště u Pacova","Hrad Kámen","Pelhřimov – Masarykovo náměstí"}'::text[], false, 20, 'approved');

  -- Přehrady a voda Vysočiny  (030_prehrady.json)
  delete from public.routes where name = 'Přehrady a voda Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Přehrady a voda Vysočiny', 'Pohodová okružní jízda po vodních dílech severně od Pelhřimova, vhodná i pro méně zkušené jezdce. Z domácí základny v Mezné vyrazíte přes Červenou Řečici k nádrži Trnávka a dál údolím řeky Želivky k premonstrátskému klášteru v Želivě. Trasa záměrně vede pouze po klidných silnicích druhé a třetí třídy a zcela se vyhýbá dálnicím, takže si užijete zvlněnou krajinu Vysočiny, lesy a hladiny přehrad. Vrcholem je monumentální hráz vodárenské nádrže Švihov (Želivka), odkud se vracíte přes Sedlickou přehradu zpět na jih. Ideální je počítat se zastávkami na koupání a fotky u vody.', 'loop', 118, 165, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – základna Mezná"}, {"lat": 49.425, "lng": 15.18, "label": "Červená Řečice"}, {"lat": 49.518, "lng": 15.212, "label": "Vodní nádrž Trnávka"}, {"lat": 49.53, "lng": 15.215, "label": "Klášter Želiv"}, {"lat": 49.676, "lng": 15.151, "label": "Vodní nádrž Švihov (Želivka)"}, {"lat": 49.51377, "lng": 15.27026, "label": "Vodní nádrž Sedlice"}, {"lat": 49.43, "lng": 15.28, "label": "Humpolec – zpáteční směr"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.425,15.18%7C49.518,15.212%7C49.53,15.215%7C49.676,15.151%7C49.51377,15.27026%7C49.43,15.28', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20%C5%BDeliv%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zahr%C3%A1dka%20-%20Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0vihov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg"}'::text[], '{"Vodní nádrž Trnávka","Klášter Želiv","Vodní nádrž Švihov (Želivka)","Vodní nádrž Sedlice"}'::text[], false, 30, 'approved');

  -- UNESCO trojúhelník – Telč, Třebíč, Zelená hora  (040_unesco.json)
  delete from public.routes where name = 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora', 'Okružní vyjížďka po třech památkách UNESCO na Vysočině vede výhradně po scénických silnicích II. a III. třídy – dálnicím a rychlostním silnicím se zcela vyhýbá. Z Mezné u Pelhřimova zamíříte na jih k renesanční Telči, odtud východními údolími řek přes Jaroměřice a Třebíč do srdce Vysočiny. Trasa nabízí svižné zatáčky, lesní úseky kolem rybníků a mírné stoupání k Zelené hoře nad Žďárem. Cesta je středně náročná, s dostatkem zastávek na prohlídky historických center a možností občerstvení ve městech.', 'poi', 215, 270, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí a zámek"}, {"lat": 49.093, "lng": 15.893, "label": "Jaroměřice nad Rokytnou"}, {"lat": 49.219, "lng": 15.877, "label": "Třebíč – bazilika a židovská čtvrť"}, {"lat": 49.35, "lng": 15.9, "label": "Náměšť nad Oslavou – průjezd"}, {"lat": 49.45, "lng": 15.94, "label": "Velké Meziříčí – průjezd"}, {"lat": 49.588, "lng": 15.942, "label": "Zelená hora, Žďár nad Sázavou"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.588,15.942&travelmode=driving&waypoints=49.184,15.453%7C49.093,15.893%7C49.219,15.877%7C49.35,15.9%7C49.45,15.94', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice_nad_rokytnou_barocco_castle_1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika-Prokopa2007.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_Zadn%C3%AD_synagoga_in_T%C5%99eb%C3%AD%C4%8D,_T%C5%99eb%C3%AD%C4%8D_District.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD_kostel_sv._Jana_Nepomuck%C3%A9ho_na_Zelen%C3%A9_ho%C5%99e.jpg"}'::text[], '{"Zámek a náměstí Telč","Zámek Jaroměřice nad Rokytnou","Bazilika sv. Prokopa v Třebíči","Židovská čtvrť Třebíč","Poutní kostel sv. Jana Nepomuckého na Zelené hoře"}'::text[], false, 40, 'approved');

  -- Údolím řeky Sázavy  (050_sazava.json)
  delete from public.routes where name = 'Údolím řeky Sázavy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolím řeky Sázavy', 'Malebná trasa sleduje kroutící se údolí řeky Sázavy proti proudu od Lipnice nad Sázavou až po Sázavský klášter a záměrně se vyhýbá dálnicím. Silnice se vinou podél řeky, střídají stoupání k hradům nad údolím s klidnými úseky mezi lesy a skalami. Nejlepší je jezdit v květnu až září, kdy je asfalt suchý a údolí nejzelenější. Pozor na úzké a místy nekvalitní vozovky, kamení a listí v zatáčkách a na frekventované úseky u hradů v hlavní turistické sezóně. Jde o středně náročnou celodenní vyjížďku s pěti zastávkami u hradů a klášterů nad řekou.', 'poi', 98, 150, 'medium',
     '[{"lat": 49.614, "lng": 15.413, "label": "Hrad Lipnice nad Sázavou"}, {"lat": 49.669, "lng": 15.404, "label": "Zámek Světlá nad Sázavou"}, {"lat": 49.696, "lng": 15.278, "label": "Hrad Ledeč nad Sázavou"}, {"lat": 49.81, "lng": 14.928, "label": "Hrad Český Šternberk"}, {"lat": 49.876, "lng": 14.898, "label": "Sázavský klášter"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.614,15.413&destination=49.876,14.898&travelmode=driving&waypoints=49.669,15.404%7C49.696,15.278%7C49.81,14.928', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Lipnice%20nad%20S%C3%A1zavou%20(27).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Lipnice%20nad%20S%C3%A1zavou%20(27).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG"}'::text[], '{"Hrad Lipnice nad Sázavou","Zámek Světlá nad Sázavou","Hrad Ledeč nad Sázavou","Hrad Český Šternberk","Sázavský klášter"}'::text[], false, 50, 'approved');

  -- Žďárské vrchy – skály a serpentiny  (060_zdarske.json)
  delete from public.routes where name = 'Žďárské vrchy – skály a serpentiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Žďárské vrchy – skály a serpentiny', 'Okruh Žďárskými vrchy vede úzkými, klikatými silnicemi skalnatou vrchovinou plnou žulových skalních měst, hlubokých lesů a rašelinišť. Trasa se úmyslně vyhýbá dálnicím i rychlostním silnicím – jede se výhradně po zvlněných okreskách plných zatáček a stoupání kolem nejvyšších vrcholů oblasti. Nejlepší je jaro až podzim; v létě si užijete stinné lesní úseky, na podzim barvy a výhledy, ale pozor na vlhké listí a chladné údolní mlhy. Buďte opatrní na úzkých hřebenových cestách, na štěrk a písek v zatáčkách po lesních pracích a na cyklisty a chodce v okolí turistických skal. Vzhledem k převýšení, technickým serpentinám a proměnlivému povrchu jde o náročnější okruh pro zkušenější jezdce.', 'loop', 118, 175, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.6636, "lng": 16.0533, "label": "Sněžné"}, {"lat": 49.66056, "lng": 16.07222, "label": "Drátník (Dráteník)"}, {"lat": 49.67079, "lng": 16.03238, "label": "Devět skal"}, {"lat": 49.68606, "lng": 16.09333, "label": "Čtyři palice"}, {"lat": 49.55497, "lng": 16.27954, "label": "Rozhledna Karasín"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.6636,16.0533%7C49.66056,16.07222%7C49.67079,16.03238%7C49.68606,16.09333%7C49.55497,16.27954', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hornosvrateck%C3%A1%20vrchovina%20(IIC-4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hornosvrateck%C3%A1%20vrchovina%20(IIC-4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg"}'::text[], '{"Skalní útvar Devět skal","Skály Čtyři palice","Skalní útvar Drátník","Rozhledna Karasín","Městys Sněžné (Milovy)"}'::text[], false, 60, 'approved');

  -- Rybníky a zámky Třeboňska  (070_trebonsko.json)
  delete from public.routes where name = 'Rybníky a zámky Třeboňska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Rybníky a zámky Třeboňska', 'Pohodová okružní jízda malebnou rybniční krajinou Třeboňska po rovinatých silnicích druhé a třetí třídy, zcela bez dálnic a rychlostních silnic. Trasa vede od renesančního zámku v Jindřichově Hradci přes pohádkový vodní zámek Červená Lhota k historickému městu Třeboň s rybníkem Svět. Cesta pokračuje po hrázi největšího rybníka v Česku – Rožmberka – lemované mohutnými duby a končí u novogotické Schwarzenberské hrobky. Silnice jsou převážně klidné, s minimem stoupání, ideální pro nenáročnou vyjížďku a focení. Počítejte s tempem odpovídajícím poznávání památek a časem na zastávky u vody.', 'poi', 118, 180, 'easy',
     '[{"lat": 49.144, "lng": 15.003, "label": "Jindřichův Hradec – zámek"}, {"lat": 49.198, "lng": 15.077, "label": "Zámek Červená Lhota"}, {"lat": 49.061, "lng": 14.804, "label": "Rybník Rožmberk – hráz"}, {"lat": 49.02, "lng": 14.783, "label": "Schwarzenberská hrobka"}, {"lat": 49.003, "lng": 14.771, "label": "Třeboň – zámek a rybník Svět"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.144,15.003&destination=49.003,14.771&travelmode=driving&waypoints=49.198,15.077%7C49.061,14.804%7C49.02,14.783', 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG"}'::text[], '{"Zámek Jindřichův Hradec","Zámek Červená Lhota","Rybník Rožmberk – hráz","Schwarzenberská hrobka","Třeboň – zámek a rybník Svět"}'::text[], false, 70, 'approved');

  -- Vltava, Orlík a Zvíkov  (080_orlik.json)
  delete from public.routes where name = 'Vltava, Orlík a Zvíkov' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Vltava, Orlík a Zvíkov', 'Malebný okruh podél Orlické přehrady a řeky Vltavy, který propojuje čtyři romantické zastávky nad rozlehlou vodní hladinou. Trasa vede výhradně po klidných silnicích druhé a třetí třídy, dálnicím a rychlostním silnicím se zcela vyhýbá. Užijete si zatáčky nad zálivy přehrady, hluboké lesy a nádherné výhledy z vysokých mostů. Ideální je zastavit na zámku Orlík, přejet Podolský most a zamířit k hradu Zvíkov nad soutokem Vltavy a Otavy. Kombinace svižných úseků a poklidných partií u vody dělá z okruhu příjemnou celodenní vyjížďku.', 'poi', 68, 110, 'medium',
     '[{"lat": 49.539, "lng": 14.164, "label": "Hráz vodní nádrže Orlík"}, {"lat": 49.5175, "lng": 14.16972, "label": "Zámek Orlík nad Vltavou"}, {"lat": 49.4, "lng": 14.29, "label": "Kostel Červená nad Vltavou"}, {"lat": 49.35645, "lng": 14.26352, "label": "Podolský most"}, {"lat": 49.437, "lng": 14.1885, "label": "Hrad Zvíkov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.539,14.164&destination=49.437,14.1885&travelmode=driving&waypoints=49.5175,14.16972%7C49.4,14.29%7C49.35645,14.26352', 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Orl%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Orl%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG"}'::text[], '{"Zámek Orlík nad Vltavou","Hrad Zvíkov","Podolský most","Vodní nádrž Orlík – hráz","Kostel Červená nad Vltavou"}'::text[], false, 80, 'approved');

  -- Husitské Táborsko a Chýnovská jeskyně  (090_taborsko.json)
  delete from public.routes where name = 'Husitské Táborsko a Chýnovská jeskyně' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Husitské Táborsko a Chýnovská jeskyně', 'Okružní jízda po malebných silnicích druhé třídy Táborskem, kompletně mimo dálnice a rychlostní komunikace. Z Mezné u Pelhřimova zamíříte přes klidné okresky do husitského Tábora, pokračujete k romantické zřícenině Kozího hrádku a dále zvlněnou krajinou na Chýnov k unikátní jeskyni. Zpáteční část vede přes Bechyni s proslulým mostem Duha a kolem rozhledny Hýlačka nad Táborem zpět na základnu. Trasa nabízí střídání táhlých zatáček v údolí Lužnice a lesních úseků, je vhodná na klidnou celodenní vyjížďku.', 'loop', 142, 215, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.4111, "lng": 14.6558, "label": "Tábor – Žižkovo náměstí a hrad Kotnov"}, {"lat": 49.39775, "lng": 14.72642, "label": "Kozí hrádek"}, {"lat": 49.42944, "lng": 14.83306, "label": "Chýnovská jeskyně"}, {"lat": 49.297, "lng": 14.469, "label": "Zámek Bechyně a most Duha"}, {"lat": 49.389, "lng": 14.643, "label": "Rozhledna Hýlačka"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.4111,14.6558%7C49.39775,14.72642%7C49.42944,14.83306%7C49.297,14.469%7C49.389,14.643', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20hr%C3%A1dek%20(01).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], '{"Tábor – Žižkovo náměstí a hrad Kotnov","Kozí hrádek","Chýnovská jeskyně","Zámek Bechyně a most Duha","Rozhledna Hýlačka"}'::text[], false, 90, 'approved');

  -- Nejlepší zatáčky Javořické vrchoviny  (100_javoricka.json)
  delete from public.routes where name = 'Nejlepší zatáčky Javořické vrchoviny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Nejlepší zatáčky Javořické vrchoviny', 'Náročný okruh po nejlepších serpentinách Javořické vrchoviny, který se drží výhradně okresek a lesních silnic a zcela se vyhýbá dálnicím. Od základny míříte přes Telč k nekonečně klikatým lesním úsekům pod nejvyšším vrcholem Vysočiny Javořicí (837 m), kde se vinou uzoučké asfaltky mezi smrčinami. Trasa protíná romantické okolí Velkého Pařezitého rybníka, žulové kraje Mrákotína a lesní hrad Roštejn, přičemž nabízí husté střídání zatáček, stoupání a klesání. Nejlepší je jaro až brzký podzim; v lesních stínech bývá i za sucha vlhko a listí či štěrk, pozor na zvěř, cyklisty a úzké krajnice bez svodidel. Ve vlhku a za šera jeďte defenzivně, povrch okresek je místy hrbolatý.', 'loop', 118, 195, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí"}, {"lat": 49.157, "lng": 15.412, "label": "Mrákotín"}, {"lat": 49.153, "lng": 15.351, "label": "Javořice 837 m"}, {"lat": 49.17, "lng": 15.4, "label": "Velký Pařezitý rybník"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.184,15.453%7C49.157,15.412%7C49.153,15.351%7C49.17,15.4%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vys%C3%ADla%C4%8D%20Jedlov%C3%A1%20hora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vys%C3%ADla%C4%8D%20Jedlov%C3%A1%20hora.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/PR%20Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%20(5).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn,%20common%202.jpg"}'::text[], '{"Javořice","Velký Pařezitý rybník","Hrad Roštejn","Zámek a náměstí Telč","Mrákotín – žulové lomy a pomník"}'::text[], false, 100, 'approved');

  -- Slavonicko a Česká Kanada  (110_slavonicko.json)
  delete from public.routes where name = 'Slavonicko a Česká Kanada' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Slavonicko a Česká Kanada', 'Malebný okruh Českou Kanadou po klidných lesních silničkách bez dálnic a rychlostních komunikací. Trasa vede mezi rybníky, borovými lesy a žulovými balvany od renesančních Slavonic přes romantickou zříceninu Landštejna a Nové Bystřice s proslulou úzkokolejkou až k majestátnímu zámku v Jindřichově Hradci. Silnice jsou úzké, málo frekventované a plné plynulých zatáček, ideální pro pohodovou jízdu tempem, které si užijete. Doporučujeme počítat s častými zastávkami na focení a odpočinek u vody. Dálnicím a hlavním tahům se celá trasa záměrně vyhýbá.', 'poi', 118, 195, 'medium',
     '[{"lat": 48.999, "lng": 15.351, "label": "Slavonice - renesanční náměstí"}, {"lat": 48.995, "lng": 15.19, "label": "Staré Město pod Landštejnem"}, {"lat": 48.9878, "lng": 15.22902, "label": "Hrad Landštejn"}, {"lat": 49.02, "lng": 15.104, "label": "Nová Bystřice - úzkokolejka"}, {"lat": 49.142, "lng": 15.003, "label": "Zámek Jindřichův Hradec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.999,15.351&destination=49.142,15.003&travelmode=driving&waypoints=48.995,15.19%7C48.9878,15.22902%7C49.02,15.104', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Byst%C5%99ice,%20n%C3%A1dra%C5%BE%C3%AD%20(01).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn-1.JPG"}'::text[], '{"Slavonice – renesanční sgrafitové náměstí","Hrad Landštejn","Nová Bystřice – úzkokolejka","Zámek Jindřichův Hradec","Rybník Osika / Staré Město pod Landštejnem"}'::text[], false, 110, 'approved');

  -- Za hradem Pernštejn a Novým Městem na Moravě  (120_pernstejn.json)
  delete from public.routes where name = 'Za hradem Pernštejn a Novým Městem na Moravě' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Za hradem Pernštejn a Novým Městem na Moravě', 'Okruh vede z Mezné u Pelhřimova přes východní Vysočinu po malebných silnicích II. a III. třídy, přičemž se zcela vyhýbá dálnicím – žádné úseky po D1 se nejedou. Trasa vás provede zvlněnou krajinou Žďárských vrchů se zatáčkovitými úseky, lesy a výhledy, ideálními pro pohodovou i svižnější jízdu. Cestou navštívíte skvěle zachovalý gotický hrad Pernštejn, poutní kostel na Zelené hoře, historické náměstí v Novém Městě na Moravě i rozhlednu Horní les. Silnice jsou převážně kvalitní, místy užší a klikaté v okolí říčních údolí Svratky, což z okruhu dělá zajímavý celodenní zážitek. Doporučujeme jet za suchého počasí, protože některé lesní úseky mohou být stinné a vlhké.', 'poi', 205, 300, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.58806, "lng": 15.94167, "label": "Zámek Žďár nad Sázavou / Zelená hora"}, {"lat": 49.56111, "lng": 16.07417, "label": "Nové Město na Moravě"}, {"lat": 49.5899, "lng": 16.34235, "label": "Rozhledna Horní les"}, {"lat": 49.55028, "lng": 16.31333, "label": "Hrad Pernštejn"}, {"lat": 49.524, "lng": 16.259, "label": "Bystřice nad Pernštejnem / Zubštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.58806,15.94167%7C49.56111,16.07417%7C49.5899,16.34235%7C49.55028,16.31333%7C49.524,16.259', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Pern%C5%A1tejn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Pern%C5%A1tejn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20na%20Morav%C4%9B,%20Hor%C3%A1ck%C3%A1%20galerie%20(04).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zelen%C3%A1%20hora%20-%20poutn%C3%AD%20kostel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rove%C4%8Dn%C3%A9%20-%20rozhledna%20Horn%C3%AD%20les,%202024-10,%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pivonice%20-%20hrad%20Zub%C5%A1tejn,%20obr01.jpg"}'::text[], '{"Hrad Pernštejn","Nové Město na Moravě – náměstí a Horácká galerie","Zámek Žďár nad Sázavou a Zelená hora","Rozhledna Horní les","Bystřice nad Pernštejnem a hrad Zubštejn"}'::text[], false, 120, 'approved');

  -- Passo dello Stelvio – král alpských průsmyků  (210_stelvio.json)
  delete from public.routes where name = 'Passo dello Stelvio – král alpských průsmyků' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Passo dello Stelvio – král alpských průsmyků', 'Legendární Passo dello Stelvio je se svými 2758 m druhým nejvyšším asfaltovým průsmykem Alp a nejvyšší silnicí italských Alp. Ze severní strany z Prata allo Stelvio čeká na motorkáře 48 očíslovaných serpentin (tornanti), které se v nekonečné kaskádě šplhají po úbočí Ortleru – jde o jednu z nejikoničtějších silnic na světě. Sjezd na jižní stranu do lázeňského Bormia je otevřenější a rychlejší, po cestě lze odbočit přes Passo Umbrail do Švýcarska. Ideální doba pro průjezd je červen až září, kdy je průsmyk spolehlivě otevřený; mimo sezonu bývá kvůli sněhu uzavřen. Počítejte s chladem a mlhou i v létě, hustým provozem cyklistů a aut o víkendech a nutností plné koncentrace v úzkých vlásenkách.', 'poi', 49, 110, 'hard',
     '[{"lat": 46.61841, "lng": 10.5914, "label": "Prato allo Stelvio (start)"}, {"lat": 46.55225, "lng": 10.51029, "label": "Trafoi"}, {"lat": 46.52861, "lng": 10.45278, "label": "Passo dello Stelvio – vrchol 2758 m"}, {"lat": 46.54306, "lng": 10.425, "label": "Passo Umbrail (odbočka do Švýcarska)"}, {"lat": 46.5, "lng": 10.41, "label": "Serpentiny jižní strany"}, {"lat": 46.46762, "lng": 10.37815, "label": "Bormio (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.61841,10.5914&destination=46.46762,10.37815&travelmode=driving&waypoints=46.55225,10.51029%7C46.52861,10.45278%7C46.54306,10.425%7C46.5,10.41', 'https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg"}'::text[], '{"Prato allo Stelvio","Passo dello Stelvio – vrchol s 48 serpentinami (2758 m)","Passo Umbrail (odbočka do Švýcarska)","Trafoi","Bormio"}'::text[], false, 210, 'approved');

  -- Grossglockner Hochalpenstraße – alpská legenda  (220_grossglockner.json)
  delete from public.routes where name = 'Grossglockner Hochalpenstraße – alpská legenda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Grossglockner Hochalpenstraße – alpská legenda', 'Grossglockner Hochalpenstraße je jedna z nejslavnějších horských panoramatických silnic v Evropě a spojuje Bruck v Salcbursku s Heiligenblutem v Korutanech. Trasa se vine 36 serpentinami vzhůru až do nadmořské výšky 2504 m u tunelu Hochtor, s odbočkou na vyhlídku Edelweißspitze ve 2571 m. Jde o placenou vyhlídkovou silnici (mýto), nikoli o dálnici – dálnicím se zcela vyhýbá a nabízí čistě zážitkovou jízdu horami. Nejlepší období je od poloviny května do konce října, mimo tuto dobu bývá silnice kvůli sněhu uzavřená. I v létě zde počítej s výrazně nižšími teplotami, náhlými změnami počasí, mlhou a chladem ve výškách – vezmi si teplé a nepromokavé oblečení a jeď opatrně v serpentinách.', 'poi', 48, 120, 'hard',
     '[{"lat": 47.286, "lng": 12.826, "label": "Bruck an der Glocknerstraße"}, {"lat": 47.121, "lng": 12.831, "label": "Edelweißspitze"}, {"lat": 47.079, "lng": 12.845, "label": "Hochtor"}, {"lat": 47.075, "lng": 12.752, "label": "Kaiser-Franz-Josefs-Höhe"}, {"lat": 47.041, "lng": 12.842, "label": "Heiligenblut"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.286,12.826&destination=47.041,12.842&travelmode=driving&waypoints=47.121,12.831%7C47.079,12.845%7C47.075,12.752', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Edelweisshuette.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Frans-Josefs-H%C3%B6he_view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG"}'::text[], '{"Bruck an der Glocknerstraße","Edelweißspitze","Hochtor","Kaiser-Franz-Josefs-Höhe","Heiligenblut"}'::text[], false, 220, 'approved');

  -- Dolomity – Sella Ronda (čtyři průsmyky)  (230_dolomity.json)
  delete from public.routes where name = 'Dolomity – Sella Ronda (čtyři průsmyky)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Dolomity – Sella Ronda (čtyři průsmyky)', 'Sella Ronda je legendární okruh kolem masivu Sella v italských Dolomitech, který spojuje čtyři vysokohorské průsmyky – Passo Pordoi, Passo Sella, Passo Gardena (Grödner Joch) a Passo Campolongo. Trasa se zcela vyhýbá dálnicím a rychlostním silnicím; jede se výhradně po klikatých horských silnicích plných serpentin a vlásenek s dechberoucími výhledy na dolomitské štíty. Nejlepší období pro jízdu je od června do září, kdy jsou průsmyky spolehlivě průjezdné a bez sněhu. Počítejte s hustým provozem cyklistů, karavanů i turistických busů, zejména v létě a o víkendech, proto jeďte defenzivně a v serpentinách předvídejte pomalá vozidla. Okruh lze projet oběma směry a je klidně zvládnutelný za jeden den s pauzami na jednotlivých sedlech.', 'loop', 52, 180, 'hard',
     '[{"lat": 46.476, "lng": 11.77, "label": "Canazei (start)"}, {"lat": 46.487, "lng": 11.812, "label": "Passo Pordoi"}, {"lat": 46.52, "lng": 11.878, "label": "Passo Campolongo"}, {"lat": 46.546, "lng": 11.81, "label": "Passo Gardena / Grödner Joch"}, {"lat": 46.557, "lng": 11.756, "label": "Selva di Val Gardena"}, {"lat": 46.508, "lng": 11.762, "label": "Passo Sella"}, {"lat": 46.476, "lng": 11.77, "label": "Canazei (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.476,11.77&destination=46.476,11.77&travelmode=driving&waypoints=46.487,11.812%7C46.52,11.878%7C46.546,11.81%7C46.557,11.756%7C46.508,11.762', 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi%202019-09-03%206.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi%202019-09-03%206.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20View%20to%20Sella%20Ronda%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg"}'::text[], '{"Passo Pordoi","Passo Sella","Passo Gardena / Grödner Joch","Passo Campolongo","Canazei / Val di Fassa"}'::text[], false, 230, 'approved');

  -- Timmelsjoch – panoramatická horská cesta  (240_timmelsjoch.json)
  delete from public.routes where name = 'Timmelsjoch – panoramatická horská cesta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Timmelsjoch – panoramatická horská cesta', 'Timmelsjoch (italsky Passo del Rombo) je jedna z nejvýše položených zpoplatněných horských silnic v Alpách, jejíž vrchol leží ve výšce 2 509 m n. m. na hranici Rakouska a Itálie. Trasa spojuje tyrolské Ötztal se severoitalským údolím Passeier a cíleně se vyhýbá dálnicím – jede se čistě po panoramatické horské cestě plné serpentin a přibližně 60 zatáček s ostrými vlásenkami a stoupáním až 12,7 %. Mýto se platí nad obcí Hochgurgl na rakouské straně a projet lze pouze přes den v letní sezóně. V zimě je silnice kvůli sněhu uzavřená, takže ideální doba pro jízdu je od června do září. Odměnou motorkářům jsou úchvatné výhledy na ledovce, moderní architektura muzeí Timmelsjoch Experience a jeden z nejlepších řidičských zážitků v Alpách.', 'poi', 35, 95, 'hard',
     '[{"lat": 46.9667, "lng": 11.0, "label": "Sölden – start v Ötztalu"}, {"lat": 46.9096, "lng": 11.0533, "label": "Hochgurgl – mýtná stanice"}, {"lat": 46.9028, "lng": 11.0967, "label": "Timmelsjoch / Passo del Rombo 2509 m"}, {"lat": 46.86, "lng": 11.12, "label": "Serpentiny italské strany"}, {"lat": 46.79436, "lng": 11.08807, "label": "Moso in Passiria / Moos in Passeier"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.9667,11.0&destination=46.79436,11.08807&travelmode=driving&waypoints=46.9096,11.0533%7C46.9028,11.0967%7C46.86,11.12', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_Total.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_am_Timmelsjoch.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG"}'::text[], '{"Sölden","Hochgurgl","Timmelsjoch / Passo del Rombo 2509 m","Top Mountain Motorcycle Museum (Passmuseum)","Moso in Passiria / Moos in Passeier"}'::text[], false, 240, 'approved');

  -- Okolo Lago di Garda  (250_garda.json)
  delete from public.routes where name = 'Okolo Lago di Garda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Okolo Lago di Garda', 'Okruh kolem největšího italského jezera Lago di Garda patří k nejkrásnějším motorkářským zážitkům v Alpách. Západní břeh vede po slavné Gardesana Occidentale, sérii serpentin a tunelů vytesaných přímo do skal nad hladinou, s dechberoucími výhledy na tyrkysovou vodu a masiv Monte Baldo. Východní břeh (Gardesana Orientale) nabízí plynulejší jízdu podél malebných městeček jako Malcesine s hradem Scaligero a lanovkou na Monte Baldo. Pozor na hustý turistický provoz v hlavní sezoně, úzké tunely bez osvětlení a cyklisty; nejlepší období je konec jara (květen–červen) a začátek podzimu (září), kdy je počasí příjemné a doprava snesitelnější. Naplánujte si celý den – zastávky u jezera, kávu na promenádě a projížďku starou silnicí Ponale nad Rivou si nenechte ujít.', 'loop', 165, 330, 'medium',
     '[{"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}, {"lat": 45.85271, "lng": 10.8812, "label": "Torbole / Ponale"}, {"lat": 45.81468, "lng": 10.79322, "label": "Limone sul Garda"}, {"lat": 45.65, "lng": 10.635, "label": "Gargnano"}, {"lat": 45.5536, "lng": 10.5675, "label": "Salò"}, {"lat": 45.49744, "lng": 10.60507, "label": "Sirmione"}, {"lat": 45.5525, "lng": 10.7596, "label": "Bardolino"}, {"lat": 45.677, "lng": 10.7157, "label": "Torri del Benaco"}, {"lat": 45.76442, "lng": 10.81024, "label": "Malcesine"}, {"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.88577,10.84117&destination=45.88577,10.84117&travelmode=driving&waypoints=45.85271,10.8812%7C45.81468,10.79322%7C45.65,10.635%7C45.5536,10.5675%7C45.49744,10.60507%7C45.5525,10.7596%7C45.677,10.7157%7C45.76442,10.81024', 'https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20014.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20014.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg"}'::text[], '{"Riva del Garda","Limone sul Garda","Malcesine","Torbole / Ponale","Sirmione"}'::text[], false, 250, 'approved');

  -- Julské Alpy – průsmyk Vršič a údolí Soči  (260_vrsic.json)
  delete from public.routes where name = 'Julské Alpy – průsmyk Vršič a údolí Soči' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Julské Alpy – průsmyk Vršič a údolí Soči', 'Ikonická horská trasa Julskými Alpami, která se zcela vyhýbá dálnicím a vede jen po úzkých panoramatických silnicích. Z Kranjské Gory stoupá 50 očíslovanými serpentinami až na Vršič (1611 m) – nejvyšší silniční průsmyk ve Slovinsku, přičemž několik zatáček na východním svahu má stále původní dlažební kostky, které jsou za deště kluzké. Za sedlem trasa klesá do romantického údolí Trenta k prameni Soče a dále podél smaragdové řeky až do městečka Bovec. Nejlepší období je od června do září, kdy je průsmyk bez sněhu; brzy zjara a na podzim hrozí led a silnice se přes zimu uzavírá. Pozor na úzkou vozovku, cyklisty, turistické autobusy a náhlé změny počasí ve výškách.', 'poi', 50, 150, 'hard',
     '[{"lat": 46.485, "lng": 13.786, "label": "Kranjska Gora – start"}, {"lat": 46.469, "lng": 13.788, "label": "Jezero Jasna"}, {"lat": 46.433, "lng": 13.747, "label": "Průsmyk Vršič 1611 m"}, {"lat": 46.409, "lng": 13.719, "label": "Pramen Soči (Trenta)"}, {"lat": 46.357, "lng": 13.635, "label": "Údolí Soči"}, {"lat": 46.338, "lng": 13.552, "label": "Bovec – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.485,13.786&destination=46.338,13.552&travelmode=driving&waypoints=46.469,13.788%7C46.433,13.747%7C46.409,13.719%7C46.357,13.635', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Milky_Way_above_Vrsic_mountain_pass_in_Julian_Alps_in_Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Brdo.jpg"}'::text[], '{"Kranjska Gora","Jezero Jasna","Průsmyk Vršič (1611 m)","Pramen Soči (Izvir Soče)","Bovec"}'::text[], false, 260, 'approved');

  -- Jadranská magistrála – chorvatské pobřeží  (270_jadran.json)
  delete from public.routes where name = 'Jadranská magistrála – chorvatské pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Jadranská magistrála – chorvatské pobřeží', 'Jadranská magistrála (Jadranska magistrala, státní silnice D8) je legendární pobřežní trasa vedoucí těsně nad hladinou Jadranu – záměrně se vyhýbá vnitrozemské dálnici A1 a nabízí nekonečné výhledy na moře, skalnaté útesy a ostrovy. Silnice se vine v serpentinách podél mohutného pohoří Velebit, střídá stoupání a klesání a odměňuje motorkáře plynulými zatáčkami s panoramaty modré vody. Nejlepší období pro jízdu je pozdní jaro (květen–červen) a začátek podzimu (září), kdy je provoz slabší a teploty snesitelnější. Pozor na nárazový vítr bóru pod Velebitem, který dokáže i za slunečného dne prudce zesílit, a na letní vedra na nechráněných úsecích. Trasa začíná u Opatije a Rijeky a míří přes Senj, Karlobag a Paklenicu až do historického Zadaru.', 'poi', 230, 300, 'medium',
     '[{"lat": 45.339, "lng": 14.306, "label": "Opatija / Rijeka – start magistrály"}, {"lat": 44.99, "lng": 14.903, "label": "Senj – pevnost Nehaj"}, {"lat": 44.529, "lng": 15.078, "label": "Karlobag pod Velebitem"}, {"lat": 44.283, "lng": 15.463, "label": "NP Paklenica"}, {"lat": 44.116, "lng": 15.226, "label": "Zadar – staré město"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.339,14.306&destination=44.116,15.226&travelmode=driving&waypoints=44.99,14.903%7C44.529,15.078%7C44.283,15.463', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg"}'::text[], '{"Opatija / Rijeka – začátek Jadranské magistrály","Senj – pevnost Nehaj","Karlobag pod Velebitem","Národní park Paklenica","Zadar – staré město a mořské varhany"}'::text[], false, 270, 'approved');

  -- Transfăgărășan – nejkrásnější silnice Karpat  (280_transfagarasan.json)
  delete from public.routes where name = 'Transfăgărășan – nejkrásnější silnice Karpat' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Transfăgărășan – nejkrásnější silnice Karpat', 'Transfăgărășan (silnice DN7C) je legendární horská cesta klikatící se přes rumunské Karpaty (pohoří Fagaraš) a rozhodně to není dálnice – celá trasa se vyhýbá rychlostním silnicím a nabízí nekonečné serpentiny stoupající až do výšky 2042 m. Cestou projedete tmavým 887 m dlouhým tunelem Bâlea těsně pod nejvyšším bodem a minete přehradu Vidraru, Drákulův hrad Poenari i ledovcové jezero Bâlea. Silnice je otevřená pouze od července do října; ve zbytku roku ji uzavírá sníh. Počítejte s proměnlivým horským počasím – i v létě zde bývá mlha, náhlé deště, chlad a mokrá vozovka, proto jeďte opatrně a s rezervou. Průměrná rychlost je kvůli zatáčkám kolem 40 km/h, na celý přejezd si vyhraďte klidně 5–6 hodin.', 'poi', 90, 360, 'hard',
     '[{"lat": 45.363, "lng": 24.634, "label": "Přehrada Vidraru"}, {"lat": 45.352, "lng": 24.635, "label": "Hrad Poenari"}, {"lat": 45.45, "lng": 24.6, "label": "Serpentiny jižní strany"}, {"lat": 45.596, "lng": 24.617, "label": "Tunel Bâlea (nejvyšší bod)"}, {"lat": 45.604, "lng": 24.617, "label": "Jezero Bâlea"}, {"lat": 45.618, "lng": 24.622, "label": "Vodopád Bâlea"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.363,24.634&destination=45.618,24.622&travelmode=driving&waypoints=45.352,24.635%7C45.45,24.6%7C45.596,24.617%7C45.604,24.617', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poenari%20Castle%20in%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg"}'::text[], '{"Přehrada Vidraru (Lacul Vidraru)","Hrad Poenari (Drákulův hrad)","Jezero Bâlea (Bâlea Lac)","Vodopád Bâlea (Cascada Bâlea)","Tunel Bâlea"}'::text[], false, 280, 'approved');

  -- Švýcarská trojice – Furka, Grimsel, Susten  (290_furka.json)
  delete from public.routes where name = 'Švýcarská trojice – Furka, Grimsel, Susten' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Švýcarská trojice – Furka, Grimsel, Susten', 'Legendární okruh přes tři vysoké alpské průsmyky – Furka (2429 m), Grimsel (2164 m) a Susten (2224 m) – patří k nejkrásnějším motorkářským trasám ve Švýcarsku a záměrně se vyhýbá dálnicím i tunelům, takže jedete výhradně po panoramatických horských silnicích. Ze sedla Furka je nádherný výhled na ledovec Rhône a slavný hotel Belvédère, u Grimselu vás ohromí tyrkysová přehradní jezera Grimselsee a Totensee. Serpentiny jsou úzké, s množstvím vlásenek a místy bez svodidel, proto vyžadují zkušenost a plnou koncentraci. Nejlepší období je červen až září, mimo tuto sezónu bývají průsmyky uzavřené kvůli sněhu. Pozor na chlad ve výškách, náhlé změny počasí, cyklisty, autobusy a vlhký asfalt ve stinných úsecích.', 'loop', 120, 180, 'hard',
     '[{"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (start)"}, {"lat": 46.7267, "lng": 8.446, "label": "Sustenpass"}, {"lat": 46.561, "lng": 8.333, "label": "Grimselpass"}, {"lat": 46.573, "lng": 8.389, "label": "Ledovec Rhône / Belvédère"}, {"lat": 46.572, "lng": 8.415, "label": "Furkapass"}, {"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.6353,8.5941&destination=46.6353,8.5941&travelmode=driving&waypoints=46.7267,8.446%7C46.561,8.333%7C46.573,8.389%7C46.572,8.415', 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rhoneglacier.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG"}'::text[], '{"Furkapass","Ledovec Rhône a Belvédère","Grimselpass","Sustenpass","Andermatt"}'::text[], false, 290, 'approved');

  -- Nockalmstraße a přehrada Kölnbreinsperre  (300_nockalm.json)
  delete from public.routes where name = 'Nockalmstraße a přehrada Kölnbreinsperre' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Nockalmstraße a přehrada Kölnbreinsperre', 'Panoramatický okruh, který spojuje dva klenoty korutanských Alp a záměrně se vyhýbá dálnicím i rychlostním silnicím. Placená Nockalmstraße stoupá 52 vlásenkami mírnými zaoblenými horami Nockberge až na svůj nejvyšší bod Eisentalhöhe ve výšce 2042 m, odkud se otevírá dech beroucí výhled. Druhým vrcholem je jízda údolím Maltatal na masivní přehradu Kölnbreinsperre, nejvyšší přehradu Rakouska (200 m), s tyrkysovým jezerem a vyhlídkovou plošinou Airwalk. Ideální sezona je od začátku května do konce října, kdy jsou obě horské silnice sjízdné; mýto na Nockalmstraße činí přibližně 18,50 € pro motorky. Trasu doplňuje odpočinek u jezera Millstätter See, druhého největšího korutanského jezera, které je perfektním místem na kávu a zchlazení nohou.', 'loop', 175, 330, 'medium',
     '[{"lat": 46.8002, "lng": 13.583, "label": "Start – Millstätter See"}, {"lat": 46.965, "lng": 13.51, "label": "Údolí Maltatal"}, {"lat": 47.078, "lng": 13.352, "label": "Kölnbreinsperre – přehrada"}, {"lat": 46.929, "lng": 13.688, "label": "Innerkrems"}, {"lat": 46.885, "lng": 13.7, "label": "Nockalmstraße – panoramatická silnice"}, {"lat": 46.883, "lng": 13.7, "label": "Eisentalhöhe 2042 m"}, {"lat": 46.7903, "lng": 13.5745, "label": "Cíl – Millstätter See"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.8002,13.583&destination=46.7903,13.5745&travelmode=driving&waypoints=46.965,13.51%7C47.078,13.352%7C46.929,13.688%7C46.885,13.7%7C46.883,13.7', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems Krems in Kärnten 20070910a.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse Eisentalhoehe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kölnbreinsperre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt am Millstaetter See und Reißeck 08112015 8850.jpg"}'::text[], '{"Nockalmstraße – panoramatická silnice","Innerkrems","Eisentalhöhe – nejvyšší bod 2042 m","Kölnbreinsperre – přehrada v údolí Maltatal","Millstätter See"}'::text[], false, 300, 'approved');

  -- Schwarzwaldhochstraße B500 – Černý les  (310_schwarzwald.json)
  delete from public.routes where name = 'Schwarzwaldhochstraße B500 – Černý les' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Schwarzwaldhochstraße B500 – Černý les', 'Schwarzwaldhochstraße (silnice B500) je legendární horská hřebenová trasa Černým lesem, která se úplně vyhýbá dálnicím a vede lázeňským městem Baden-Baden až do Freudenstadtu. Čeká vás svižná jízda po plynulých táhlých zatáčkách s nádhernými výhledy do zalesněných údolí, kolem horského jezera Mummelsee a vrcholů Schliffkopf a Ruhestein. Cesta je vyhlášená mezi motorkáři a najdete tu řadu oblíbených motokaváren a horských hospod ideálních k zastávce. Nejlepší období je od května do října; mimo sezónu a po ránu se na exponovaných úsecích drží mlha a vlhko. Pozor na turistický provoz a autobusy o víkendech, na možný štěrk a listí v zatáčkách a v horských partiích na náhlé změny počasí a nižší teploty.', 'poi', 60, 110, 'medium',
     '[{"lat": 48.761, "lng": 8.241, "label": "Baden-Baden – start"}, {"lat": 48.593, "lng": 8.207, "label": "Mummelsee"}, {"lat": 48.56, "lng": 8.22, "label": "Ruhestein"}, {"lat": 48.535, "lng": 8.216, "label": "Schliffkopf"}, {"lat": 48.463, "lng": 8.411, "label": "Freudenstadt – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.761,8.241&destination=48.463,8.411&travelmode=driving&waypoints=48.593,8.207%7C48.56,8.22%7C48.535,8.216', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzwaldhochstrasse_Mummelsee.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baiersbronn_-_Ruhesteinstra%C3%9Fe_-_Ruhestein-Sch%C3%A4nke_02_ies.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Schwarzwald.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt_-_Marktplatz_Kirche.JPG"}'::text[], '{"Baden-Baden","Mummelsee","Ruhestein","Schliffkopf","Freudenstadt"}'::text[], false, 310, 'approved');

  -- Slovinský kras – Postojnská jeskyně a Škocjan  (320_postojna.json)
  delete from public.routes where name = 'Slovinský kras – Postojnská jeskyně a Škocjan' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, is_active, sort_order, status)
  values (v_route, v_branch, 'Slovinský kras – Postojnská jeskyně a Škocjan', 'Okruh Slovinským krasem vede po klikatých silnicích krasové planiny a záměrně se vyhýbá dálnicím – jedete jen scénickými silnicemi mezi vápencovými poli, škrapy a dubovými lesy. Srdcem trasy je proslulá Postojnská jeskyně, do jejíhož nitra vás zaveze legendární podzemní vláček, a nedaleký hrad Predjama vestavěný přímo do ústí jeskyně ve skalní stěně. Dále pokračujete k UNESCEM chráněným Škocjanským jeskyním s obřím podzemním kaňonem řeky Reky a k hřebčínu lipicánů v Lipici. Cestou můžete stočit kola i k záhadnému mizejícímu Cerknickému jezeru. Jeskyně jsou přístupné a působivé po celý rok, takže tato trasa je vděčná v každém ročním období.', 'poi', 95, 180, 'medium',
     '[{"lat": 45.75028, "lng": 14.36389, "label": "Cerkniško jezero"}, {"lat": 45.78127, "lng": 14.20571, "label": "Postojnská jeskyně"}, {"lat": 45.8092, "lng": 14.1227, "label": "Hrad Predjama"}, {"lat": 45.66317, "lng": 13.98932, "label": "Škocjanské jeskyně"}, {"lat": 45.66737, "lng": 13.88005, "label": "Lipica"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.75028,14.36389&destination=45.66737,13.88005&travelmode=driving&waypoints=45.78127,14.20571%7C45.8092,14.1227%7C45.66317,13.98932', 'https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20Cave%20-%20Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20Cave%20-%20Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg"}'::text[], '{"Postojnská jeskyně","Hrad Predjama","Škocjanské jeskyně","Lipica","Cerknické jezero"}'::text[], false, 320, 'approved');

  raise notice 'Seed tras hotov: 24 tras vloženo k pobočce %', v_branch;
