  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodní nádrž Trnávka', 'Přehrada na řece Trnavě mezi Želivem a Červenou Řečicí, vybudovaná v letech 1977–1981. Původně měla zachytávat splaveniny před vodárenskou nádrží Švihov, dnes slouží i k rekreaci a koupání. Pro motorkáře je to příjemná zastávka s možností občerstvení a klidnou hladinou obklopenou lesy.', 49.518, 15.212, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG"}'::text[], 0),
    (v_route, 'Klášter Želiv', 'Premonstrátský klášter založený roku 1139, jehož barokní podobu navrhl slavný architekt Jan Blažej Santini-Aichel. Areál nabízí prohlídky, klášterní pivovar i kavárnu, což je ideální pastva pro tělo i ducha při zastávce na trase. Leží přímo v údolí Želivky, takže sem pohodlně dojedete klidnými silnicemi bez nutnosti dálnice.', 49.53, 15.215, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20%C5%BDeliv%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20%C5%BDeliv%20(1).jpg"}'::text[], 1),
    (v_route, 'Vodní nádrž Švihov (Želivka)', 'Největší vodárenská nádrž v Česku i střední Evropě, jejíž sypaná hráz je vysoká 58 metrů a dlouhá 850 metrů. Nádrž zásobuje pitnou vodou Prahu a její okolí, a proto je většina břehů chráněná a koupání zakázané. Z okolních silnic a mostů se ale otevírají velkolepé výhledy na táhlé rameno přehrady – ideální bod obratu celé okružní jízdy.', 49.676, 15.151, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zahr%C3%A1dka%20-%20Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0vihov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zahr%C3%A1dka%20-%20Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0vihov.JPG"}'::text[], 2),
    (v_route, 'Vodní nádrž Sedlice', 'Nejstarší přehrada na Želivce, vybudovaná v letech 1921–1927 zhruba 7 km jihozápadně od Humpolce. Zděná hráz s vodní elektrárnou je od roku 2012 kulturní památkou a hladina obklopená lesy láká k rybaření i klidné zastávce. Přístupová cesta vede malebnými zatáčkami po silnicích nižších tříd, přesně v duchu této pohodové trasy mimo dálnice.', 49.51377, 15.27026, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg"}'::text[], 3);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek a náměstí Telč', 'Renesanční perla Vysočiny s jedinečným dlouhým náměstím Zachariáše z Hradce, lemovaným barevnými měšťanskými domy s podloubím. Zámek s nádhernými sály a arkádovým nádvořím patří od roku 1992 na seznam UNESCO. Ideální zastávka na kávu i procházku pěší zónou – motorku pohodlně zaparkujete kousek za historickým jádrem.', 49.184, 15.453, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tel%C4%8D.jpg"}'::text[], 0),
    (v_route, 'Zámek Jaroměřice nad Rokytnou', 'Jeden z největších barokních zámeckých komplexů v Česku s rozlehlou francouzskou zahradou a chrámem sv. Markéty. Monumentální stavba hraběte Questenberga byla ve své době centrem hudebního života Moravy. Klidná zastávka na trase mezi Telčí a Třebíčí, kde se dá protáhnout v parku a nadechnout před další jízdou.', 49.093, 15.893, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice_nad_rokytnou_barocco_castle_1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice_nad_rokytnou_barocco_castle_1.jpg"}'::text[], 1),
    (v_route, 'Bazilika sv. Prokopa v Třebíči', 'Vrcholně románsko-gotická bazilika z 13. století je považována za skvost středoevropské sakrální architektury a je součástí UNESCO. Ohromí vás mohutná klenba, rozetové okno a unikátní krypta. Stojí nad městem u bývalého benediktinského kláštera – z motorky sem dojedete přímo do areálu zámku.', 49.22, 15.874, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika-Prokopa2007.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika-Prokopa2007.JPG"}'::text[], 2),
    (v_route, 'Židovská čtvrť Třebíč', 'Nejzachovalejší židovské ghetto ve střední Evropě a jediná židovská památka mimo Izrael zapsaná samostatně na seznam UNESCO. Spleť úzkých uliček, dvě synagogy a starý hřbitov vás přenesou o staletí zpět. Čtvrť leží jen pár kroků od baziliky, obojí se dá pohodlně spojit do jedné zastávky.', 49.218, 15.879, 'https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_Zadn%C3%AD_synagoga_in_T%C5%99eb%C3%AD%C4%8D,_T%C5%99eb%C3%AD%C4%8D_District.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_Zadn%C3%AD_synagoga_in_T%C5%99eb%C3%AD%C4%8D,_T%C5%99eb%C3%AD%C4%8D_District.JPG"}'::text[], 3),
    (v_route, 'Poutní kostel sv. Jana Nepomuckého na Zelené hoře', 'Geniální barokně-gotická stavba architekta Jana Blažeje Santiniho-Aichela na kopci nad Žďárem, celá založená na symbolice čísla pět a tvaru hvězdy. Od roku 1994 je zapsána na seznamu UNESCO a patří k nejoriginálnějším sakrálním stavbám Evropy. Závěrečný cíl vyjížďky nabízí krásný výhled a klidné zákoutí k odpočinku po celodenní jízdě.', 49.588, 15.942, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD_kostel_sv._Jana_Nepomuck%C3%A9ho_na_Zelen%C3%A9_ho%C5%99e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD_kostel_sv._Jana_Nepomuck%C3%A9ho_na_Zelen%C3%A9_ho%C5%99e.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Lipnice nad Sázavou', 'Mohutný gotický hrad ze 14. století se tyčí na skalním ostrohu nad městečkem a patří k největším v Čechách. Z jeho hradeb je nádherný rozhled do údolí Sázavy a k blízkému lomu, kde je pochován spisovatel Jaroslav Hašek. Pro motorkáře je to ideální první zastávka s parkováním pod hradem a příjemnou vyhlídkou.', 49.614, 15.413, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Lipnice%20nad%20S%C3%A1zavou%20(27).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Lipnice%20nad%20S%C3%A1zavou%20(27).jpg"}'::text[], 0),
    (v_route, 'Zámek Světlá nad Sázavou', 'Klasicistně přestavěný zámek s rozlehlým anglickým parkem leží přímo nad řekou Sázavou. Areál s kašnou, skleníkem a klidnými zákoutími nabízí příjemnou přestávku uprostřed trasy. Silnice sem vede pohodovým údolím a nabízí plynulou jízdu.', 49.669, 15.404, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek1.jpg"}'::text[], 1),
    (v_route, 'Hrad Ledeč nad Sázavou', 'Gotický hrad s dominantní válcovou věží stráží řeku Sázavu z vysokého skalnatého ostrohu nad městem. Z nádvoří i z okolí se otevírají pěkné pohledy na řeku a historické jádro Ledče. Cesta k hradu vede malebným údolím se svižnými zatáčkami.', 49.696, 15.278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG"}'::text[], 2),
    (v_route, 'Hrad Český Šternberk', 'Jeden z nejlépe dochovaných gotických hradů v Čechách se dramaticky vypíná na skalním hřebeni přímo nad řekou Sázavou. Nejkrásnější pohled je z mostu přes řeku, odkud hrad působí jako z pohádky. Přístupová silnice údolím patří k nejhezčím úsekům celé trasy.', 49.81, 14.928, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG"}'::text[], 3),
    (v_route, 'Sázavský klášter', 'Benediktinský klášter založený svatým Prokopem roku 1032 leží nad řekou Sázavou a je kolébkou slovanské vzdělanosti v Čechách. Areál s nedostavěným gotickým chrámem svatého Prokopa tvoří klidný a působivý závěr celé vyjížďky. Okolní silnice podél řeky jsou svižné a scénické.', 49.876, 14.898, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Skalní útvar Devět skal', 'Devět skal je s nadmořskou výškou 836 m nejvyšší bod Žďárských vrchů a druhý nejvyšší vrchol celé Českomoravské vrchoviny. Skalní labyrint tvoří tři dlouhé hřebeny s devíti mohutnými žulovými věžemi, ke kterým dojedete po klikatých lesních silnicích. Ideální zastávka na protažení nohou a rozhled do drsné vrchoviny.', 49.67079, 16.03238, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hornosvrateck%C3%A1%20vrchovina%20(IIC-4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hornosvrateck%C3%A1%20vrchovina%20(IIC-4).jpg"}'::text[], 0),
    (v_route, 'Skály Čtyři palice', 'Čtyři palice jsou nápadné migmatitové skály nad Milovy, tvořící přírodní rezervaci s bučinami a bory. Hlavní skupina skal dosahuje výšky kolem 33 metrů a je vyhledávaným cílem horolezců i turistů. Pro motorkáře je okolí odměnou v podobě úzkých zatáček a lesních průsmyků.', 49.68606, 16.09333, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg"}'::text[], 1),
    (v_route, 'Skalní útvar Drátník', 'Drátník (též Dráteník či Drátenická skála) je téměř 200 metrů dlouhý skalní hřeben a jedna z nejvýraznějších dominant střední části CHKO Žďárské vrchy. Leží na zalesněném vrcholu mezi Blatinami a Samotínem ve výšce okolo 775 m. Cesta k němu vede tichými lesními okreskami plnými zatáček.', 49.66056, 16.07222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg"}'::text[], 2),
    (v_route, 'Rozhledna Karasín', 'Rozhledna Karasín u Bystřice nad Pernštejnem stojí ve výšce kolem 619 m a nabízí po 128 schodech kruhový výhled na jižní část Žďárských vrchů. Je to skvělá zastávka na jižním konci okruhu, k níž vede příjemná zvlněná silnice. Vstup bývá zdarma a v okolí je dostatek místa k zaparkování motorky.', 49.55497, 16.27954, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg"}'::text[], 3),
    (v_route, 'Městys Sněžné (Milovy)', 'Sněžné je horský městys v srdci Žďárských vrchů, ke kterému patří i osada Milovy pod skalami. Nabízí občerstvení, ubytování a je ideálním výchozím bodem pro okolní skalní útvary jako Drátník a Čtyři palice. Barokní kostel a klidné náměstí lákají k zastávce a doplnění sil.', 49.6636, 16.0533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Jindřichův Hradec', 'Třetí největší zámecký komplex v Česku, malebně položený nad řekou Nežárkou a rybníkem Vajgar. Rozsáhlý renesanční areál s arkádovými nádvořími a unikátním hudebním pavilonem Rondel je skvělým startem trasy. Přímo pod hradbami najdete klidná parkovací místa i příjemné kavárny pro první zastávku.', 49.144, 15.003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG"}'::text[], 0),
    (v_route, 'Zámek Červená Lhota', 'Pohádkový vodní zámek s jasně červenou fasádou, který se zrcadlí na hladině rybníka a je přístupný jen po kamenném mostě. Patří k nejfotogeničtějším místům jižních Čech a k zámku vede příjemná klikatá silnička lesem. Ideální místo na krátkou procházku kolem vody a odpočinek v sedle.', 49.198, 15.077, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg"}'::text[], 1),
    (v_route, 'Rybník Rožmberk – hráz', 'Největší rybník v Česku o rozloze téměř 490 hektarů, vybudovaný Jakubem Krčínem v 16. století. Po jeho monumentální hrázi lemované staletými duby vede klidná cesta s nádhernými výhledy na vodní hladinu. Rovinatý úsek je jako stvořený pro pomalou vyjížďku a zastávku u vody.', 49.061, 14.804, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG"}'::text[], 2),
    (v_route, 'Schwarzenberská hrobka', 'Novogotická rodová hrobka Schwarzenbergů z let 1874–1877, ukrytá v anglickém parku u břehu rybníka Svět. Bílá stavba obklopená zelení působí nezvykle klidně a romanticky. K hrobce vede příjemná cesta parkem, kde se dá pěkně protáhnout po delší jízdě.', 49.02, 14.783, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG"}'::text[], 3),
    (v_route, 'Třeboň – zámek a rybník Svět', 'Historické lázeňské město s dochovaným renesančním jádrem, zámkem a hradbami, obklopené sítí rybníků. Rybník Svět přímo u města láká k procházce po hrázi i k občerstvení v přilehlých restauracích. Ideální cíl trasy s dostatkem parkování a možností delší zastávky.', 49.003, 14.771, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Orlík nad Vltavou', 'Romantický zámek rodu Schwarzenbergů stojí na skalnatém ostrohu přímo nad hladinou Orlické přehrady. Původně gotický hrad byl přestavěn do dnešní novogotické podoby a obklopuje jej rozlehlý anglický park. Pro motorkáře je to ideální zastávka s parkováním a výhledy na vodu, odkud lze pokračovat podél přehrady dál.', 49.5175, 14.16972, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Orl%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Orl%C3%ADk.jpg"}'::text[], 0),
    (v_route, 'Hrad Zvíkov', 'Zvíkov, přezdívaný král českých hradů, se tyčí na skalním ostrohu nad soutokem Vltavy a Otavy. Patří k nejvýznamnějším raně gotickým hradům u nás a jeho arkádové nádvoří i Hlízová věž stojí za prohlídku. Cesta k hradu vede úzkými zatáčkami nad přehradou a nabízí strhující výhledy.', 49.437, 14.1885, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG"}'::text[], 1),
    (v_route, 'Podolský most', 'Impozantní obloukový most přes zátoku Orlické přehrady patří k technickým skvostům své doby a klene se ve velké výšce nad vodní hladinou. Přejezd po tomto vysokém mostě je pro motorkáře nezapomenutelný zážitek s panoramatem na řeku Vltavu. U mostu se dá zastavit a pokochat se pohledem do hloubky.', 49.35645, 14.26352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg"}'::text[], 2),
    (v_route, 'Vodní nádrž Orlík – hráz', 'Mohutná betonová hráz Orlické přehrady o výšce 91 metrů zadržuje druhou největší vodní nádrž v Česku. Vznikla v rámci Vltavské kaskády v letech 1954 až 1961 a nabízí pohled na strojní srdce celé přehrady. Silnice v okolí hráze jsou svižné a lemované lesy, ideální pro klidnou jízdu.', 49.539, 14.164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG"}'::text[], 3),
    (v_route, 'Kostel Červená nad Vltavou', 'Kostel svatého Bartoloměje je poslední památkou na vesnici Červená nad Vltavou, kterou pohltily vody přehrady. Před zaplavením byl přenesen výše nad údolí, kde dnes osaměle stojí nad vodní hladinou v malebné krajině. Klidné místo stranou hlavních cest je příjemnou zastávkou na okruhu podél Vltavy.', 49.4, 14.29, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20Reservoir%20in%20winter%202010-2011%20(2).JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tábor – Žižkovo náměstí a hrad Kotnov', 'Historické jádro Tábora s malebným Žižkovým náměstím a věží Kotnov je srdcem husitského hnutí a městskou památkovou rezervací. Věž hradu Kotnov spolu s Bechyňskou branou tvoří dominantu města nad údolím Lužnice. Pro motorkáře je to ideální zastávka na kávu v dlážděných uličkách i vstup do slavného táborského podzemí.', 49.4111, 14.6558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG"}'::text[], 0),
    (v_route, 'Kozí hrádek', 'Romantická zřícenina gotického hrádku ukrytá v lese u Sezimova Ústí, kde v letech 1413–1414 pobýval a kázal mistr Jan Hus. Národní kulturní památka láká na klidnou procházku hlubokým lesem k dochovaným zdem a příkopům. Skvělé místo na krátký oddech mimo ruch silnic.', 49.39775, 14.72642, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20hr%C3%A1dek%20(01).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20hr%C3%A1dek%20(01).jpg"}'::text[], 1),
    (v_route, 'Chýnovská jeskyně', 'Nejstarší zpřístupněná jeskyně v Česku, otevřená veřejnosti už od roku 1868, s výraznou barevnou hrou bílého mramoru a tmavé amfibolitové horniny. Prohlídková trasa vede strmými schody podzemím se zajímavými geologickými útvary a je významným zimovištěm netopýrů. Příjemné osvěžení v horkém dni po jízdě zvlněnou krajinou.', 49.42944, 14.83306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg"}'::text[], 2),
    (v_route, 'Zámek Bechyně a most Duha', 'Renesanční zámek Bechyně stojí na skalním ostrohu nad soutokem Smutné a Lužnice a spolu s klenutým železobetonovým mostem Duha z roku 1928 tvoří jeden z nejfotogeničtějších pohledů jižních Čech. Most se klene 50 metrů nad hladinou řeky a nabízí dech beroucí výhled do údolí. Zastávka spojující historii, techniku i krásnou přírodu.', 49.297, 14.469, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG"}'::text[], 3),
    (v_route, 'Rozhledna Hýlačka', 'Dřevěná rozhledna na kopci Hýlačka v lokalitě Větrovy nad Táborem ve výšce přes 500 metrů nad mořem nabízí kruhový rozhled po Táborsku a za dobrého počasí až k šumavským hřebenům. Znovupostavená věž je oblíbeným výletním cílem s posezením v okolí. Ideální tečka výletu s výhledem, než se vydáte zpět na základnu.', 49.389, 14.643, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Javořice', 'Nejvyšší vrchol Vysočiny a celé Českomoravské vrchoviny (837 m) s výrazným televizním vysílačem z roku 1989. K vrcholu vedou úzké lesní asfaltky plné zatáček, které patří k nejlepším v kraji. Kousek pod vrcholem je vyhlídková plošina s výhledem k Telči. Ideální zastávka pro motorkáře hledající klid hlubokých smrčin.', 49.153, 15.351, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vys%C3%ADla%C4%8D%20Jedlov%C3%A1%20hora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vys%C3%ADla%C4%8D%20Jedlov%C3%A1%20hora.jpg"}'::text[], 0),
    (v_route, 'Velký Pařezitý rybník', 'Přírodní rezervace a oblíbený rybník u Řásné, který nechal založit Zachariáš z Hradce roku 1565. Leží ve výšce kolem 670 m obklopen lesy a rašeliništi, koupání je zde povolené. Skvělé místo na osvěžení a odpočinek uprostřed klikaté lesní trasy. Okolní silničky nabízejí příjemné zatáčky ve stínu stromů.', 49.17, 15.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/PR%20Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%20(5).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/PR%20Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%20(5).JPG"}'::text[], 1),
    (v_route, 'Hrad Roštejn', 'Romantický lovecký hrad ukrytý v lesích Roštejnské obory, dominantou je sedmiboká věž. Původně gotická tvrz sloužila pánům z Hradce jako lovecké sídlo v nadmořské výšce kolem 670 m. Přístupová lesní cesta je klikatá a atmosférická, ideální pro pomalou svižnou jízdu. Vhodná zastávka na prohlídku i piknik v tichu lesa.', 49.272, 15.484, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG"}'::text[], 2),
    (v_route, 'Zámek a náměstí Telč', 'Renesanční klenot na seznamu UNESCO od roku 1992 s dlouhým náměstím Zachariáše z Hradce lemovaným podloubími a štíty. Nad městem se tyčí renesanční zámek Zachariáše z Hradce mezi dvěma rybníky. Skvělá zastávka na kávu a fotky uprostřed okruhu. Dlažba náměstí bývá kluzká, jeďte opatrně.', 49.184, 15.453, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg"}'::text[], 3),
    (v_route, 'Mrákotín – žulové lomy a pomník', 'Městys proslulý těžbou žuly už od 19. století; odtud pochází monolit na třetím nádvoří Pražského hradu vylámaný roku 1925. Na náměstí stojí žulový pomník padlým z roku 1937 postavený místními lomaři. Okolní silničky ke Studené a k Javořici patří mezi nejzatáčkovitější v oblasti. Pěkná zastávka pro milovníky kamene i klikatého asfaltu.', 49.157, 15.412, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn,%20common%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn,%20common%202.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Slavonice – renesanční sgrafitové náměstí', 'Slavonice na pomezí Čech, Moravy a Rakouska okouzlí dvěma náměstími lemovanými měšťanskými domy s podloubím a bohatou renesanční sgrafitovou výzdobou ze 16. století. Pro motorkáře je to ideální cíl k procházce historickým jádrem a pauze v některé z kaváren. Město je zároveň skvělou vstupní branou do malebné krajiny České Kanady.', 48.999, 15.351, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg"}'::text[], 0),
    (v_route, 'Hrad Landštejn', 'Mohutná románsko-gotická zřícenina Landštejna se tyčí na skalnatém návrší nad lesy České Kanady a patří k nejlépe dochovaným románským pevnostem u nás. Z vyhlídkové věže se otevírá dechberoucí rozhled do širokého okolí až k rakouským hranicím. Přístupová silnička plná zatáček je pro motorkáře zážitkem sama o sobě.', 48.9878, 15.22902, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg"}'::text[], 1),
    (v_route, 'Nová Bystřice – úzkokolejka', 'Nová Bystřice je koncovou stanicí historické úzkorozchodné dráhy z Jindřichova Hradce, otevřené již v roce 1897. U nádraží se dají obdivovat staré parní i motorové lokomotivy a nasát atmosféru romantické železnice. Okolní silnice České Kanady jsou úzké a lesnaté, jako stvořené pro klidnou vyjížďku.', 49.02, 15.104, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Byst%C5%99ice,%20n%C3%A1dra%C5%BE%C3%AD%20(01).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Byst%C5%99ice,%20n%C3%A1dra%C5%BE%C3%AD%20(01).jpg"}'::text[], 2),
    (v_route, 'Zámek Jindřichův Hradec', 'Rozlehlý zámecký komplex v Jindřichově Hradci patří k největším v Česku a vznikl přestavbou původního gotického hradu nad soutokem Nežárky a rybníka Vajgar. Nádvoří s renesančními arkádami a proslulá kruhová Rondel jsou skvostem jihočeské architektury. Historické centrum města nabízí motorkářům příjemné zázemí k delší přestávce.', 49.142, 15.003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG"}'::text[], 3),
    (v_route, 'Rybník Osika / Staré Město pod Landštejnem', 'Staré Město pod Landštejnem leží v srdci České Kanady mezi Slavonicemi a Novou Bystřicí, obklopené lesy a rybníky. Nedaleký rybník Osika i další vodní plochy lákají v létě ke koupání a osvěžení po jízdě. Klidné silnice s minimálním provozem vedou zvlněnou krajinou plnou žulových balvanů a borových hájů.', 48.995, 15.19, 'https://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn-1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn-1.JPG"}'::text[], 4);
