  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Prato allo Stelvio', 'Jihotyrolská obec Prato allo Stelvio (německy Prad am Stilfserjoch) v nadmořské výšce kolem 915 m je klasickým startem výjezdu na Stelvio ze severní strany. Zde se doplňuje nádrž i síly před 48 serpentinami. Poklidné alpské městečko s dobrým zázemím pro motorkáře je bránou do celé oblasti Ortleru.', 46.61841, 10.5914, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG"}'::text[], 0),
    (v_route, 'Passo dello Stelvio – vrchol s 48 serpentinami (2758 m)', 'Vrchol Stelvia ve výšce 2758 m je svatým grálem alpských motorkářů – nejvyšší silniční průsmyk Itálie a druhý nejvyšší v Alpách. Severní stranu tvoří 48 očíslovaných vlásenek, které tvoří slavnou kamennou kaskádu pod ledovcem Ortleru. Na vrcholu najdete stánky, občerstvení a nezaměnitelný výhled, ale i chlad a proměnlivé počasí i v létě.', 46.52861, 10.45278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG"}'::text[], 1),
    (v_route, 'Passo Umbrail (odbočka do Švýcarska)', 'Kousek pod vrcholem Stelvia odbočuje na Passo Umbrail (2501 m), nejvýše položenou silnici Švýcarska. Průsmyk vede z italské strany do údolí Val Müstair a nabízí klidnější alternativu k přetíženému Stelviu. Pro motorkáře je to skvělá zajížďka spojující dva státy a dvě dechberoucí panoramata.', 46.54306, 10.425, 'https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG"}'::text[], 2),
    (v_route, 'Trafoi', 'Malebná horská obec Trafoi (asi 1540 m) leží přímo pod hlavní kaskádou serpentin na severní straně Stelvia. Je posledním sídlem před náročným výstupem a poskytuje úchvatný pohled na masiv Ortleru. Ideální místo na krátkou zastávku, kávu a fotku před soubojem s vlásenkami.', 46.55225, 10.51029, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg"}'::text[], 3),
    (v_route, 'Bormio', 'Lázeňské městečko Bormio (asi 1225 m) v údolí Valtellina je cílem na jižní straně Stelvia a známé svými termálními prameny. Po náročném sjezdu je to příjemné místo k odpočinku, s historickým centrem a bohatou nabídkou restaurací. Slouží také jako křižovatka pro další legendární průsmyky jako Gavia či Foscagno.', 46.46762, 10.37815, 'https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg"}'::text[], 4);
