  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bruck an der Glocknerstraße', 'Salcburská obec na severním úpatí Vysokých Taur je oficiálním startovním bodem Grossglockner Hochalpenstraße. Odtud se vydáváš vzhůru do hor, ještě než začnou první serpentiny. Ideální místo na doplnění paliva a poslední kávu před náročným výjezdem.', 47.286, 12.826, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG"}'::text[], 0),
    (v_route, 'Edelweißspitze', 'Nejvyšší přístupný bod celé silnice ve výšce 2571 m, kam vede krátká dlážděná odbočka plná ostrých serpentin. Z vrcholové vyhlídky se otevírá kruhový výhled na více než 30 alpských vrcholů. Dlažba bývá kluzká, proto zde jeď opatrně a v klidu.', 47.121, 12.831, 'https://commons.wikimedia.org/wiki/Special:FilePath/Edelweisshuette.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Edelweisshuette.JPG"}'::text[], 1),
    (v_route, 'Hochtor', 'Průsmyk a tunel Hochtor ve výšce 2504 m tvoří nejvyšší bod hlavní trasy a historickou hranici mezi Salcburskem a Korutany. Tunel pod vrcholem hřebene je vytesán do skály a i v létě zde bývá výrazně chladno. Za tunelem se ti otevře pohled na korutanskou stranu Vysokých Taur.', 47.079, 12.845, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG"}'::text[], 2),
    (v_route, 'Kaiser-Franz-Josefs-Höhe', 'Slavná vyhlídková terasa na konci boční odbočky nabízí přímý pohled na nejvyšší horu Rakouska Grossglockner (3798 m) a ledovec Pasterze. Je zde velké parkoviště, návštěvnické centrum i restaurace. Jedno z nejfotografovanějších míst celé trasy a povinná zastávka každého motorkáře.', 47.075, 12.752, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Frans-Josefs-H%C3%B6he_view.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Frans-Josefs-H%C3%B6he_view.JPG"}'::text[], 3),
    (v_route, 'Heiligenblut', 'Malebná horská obec na korutanském konci silnice, proslulá gotickým kostelem sv. Vincence s vysokou štíhlou věží na pozadí masivu Grossglockneru. Tvoří jižní bránu celé trasy a je oblíbeným cílem pro odpočinek. Skvělé místo, kde zakončit legendární alpskou jízdu.', 47.041, 12.842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Passo Pordoi', 'Nejvyšší bod okruhu Sella Ronda ve výšce 2239 m mezi masivem Sella a Marmoladou. Slavný horský průsmyk s množstvím serpentin, který milují motorkáři i cyklisté – stoupá se sem po 33 vlásenkách. Na vrcholu najdete lanovku na Sass Pordoi, restaurace a pomník cyklisty Fausta Coppiho.', 46.487, 11.812, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi%202019-09-03%206.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi%202019-09-03%206.jpg"}'::text[], 0),
    (v_route, 'Passo Sella', 'Průsmyk ve výšce 2244 m nabízí snad nejúchvatnější výhledy celé trasy – přímo pod majestátní skupinou Sassolungo (Langkofel). Klikatá silnice s ostrými zatáčkami je rájem pro řidiče, kteří si užijí jak jízdu, tak panorama. Na sedle je horská chata a odpočinkové místo s parkovištěm.', 46.508, 11.762, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg"}'::text[], 1),
    (v_route, 'Passo Gardena / Grödner Joch', 'Severní vrchol okruhu ve výšce 2121 m spojuje Val Gardena s Alta Badia. Průsmyk lemují travnaté louky a strmé dolomitské stěny, silnice je zde o něco plynulejší, ale stále bohatá na zatáčky. U sedla stojí Rifugio Frara a nabízí se odsud výhled na skupinu Sella i Sassolungo.', 46.546, 11.81, 'https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg"}'::text[], 2),
    (v_route, 'Passo Campolongo', 'Nejnižší z průsmyků okruhu (1875 m) spojuje Arabbu s Corvarou v Alta Badia. Kratší a mírnější stoupání s krásnými výhledy na masiv Sella je příjemným oddechem mezi náročnějšími sedly. Oblíbený úsek slavného cyklistického závodu Maratona dles Dolomites.', 46.52, 11.878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20View%20to%20Sella%20Ronda%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20View%20to%20Sella%20Ronda%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Canazei / Val di Fassa', 'Malebná horská obec v údolí Val di Fassa je ideálním výchozím bodem okruhu Sella Ronda. Nabízí ubytování, restaurace, čerpací stanice i servis – vše, co motorkář před náročnou trasou ocení. Z Canazei se vydáte na Passo Pordoi nebo Passo Sella a uzavřete kolem masivu Sella celý okruh.', 46.476, 11.77, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sölden', 'Sölden je známé horské středisko v rakouském údolí Ötztal a přirozený výchozí bod pro jízdu na Timmelsjoch. Leží ve výšce 1 377 m n. m. a nabízí spoustu možností k občerstvení, natankování i přenocování před náročným výjezdem do hor. Odsud pokračuje silnice přes Zwieselstein a Obergurgl směrem k mýtné stanici.', 46.9667, 11.0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg"}'::text[], 0),
    (v_route, 'Hochgurgl', 'Hochgurgl je poslední osada na rakouské straně před vrcholem průsmyku a najdeš tu mýtnou stanici Top Mountain Crosspoint, kde se platí za průjezd. Ve výšce kolem 2 175 m n. m. odsud začíná nejkrásnější serpentinová část silnice. Je to ideální místo na zastávku, tankování a poslední kávu před stoupáním na hřeben.', 46.9096, 11.0533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg"}'::text[], 1),
    (v_route, 'Timmelsjoch / Passo del Rombo 2509 m', 'Nejvyšší bod celé trasy ve výšce 2 509 m n. m. leží přímo na hranici mezi Rakouskem a Itálií. Na vrcholu stojí symbolická stavba Pass Museum, která doslova překračuje hranici obou zemí a je součástí projektu Timmelsjoch Experience. Otevírá se odsud dechberoucí panoráma Ötztalských Alp a ledovců – povinná fotozastávka každého motorkáře.', 46.9028, 11.0967, 'https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_Total.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_Total.jpg"}'::text[], 2),
    (v_route, 'Top Mountain Motorcycle Museum (Passmuseum)', 'Nejvýše položené motorkářské muzeum v Evropě (2 175 m n. m.) v Hochgurglu vystavuje kolem 450 historických motocyklů a automobilů v moderní dřevěné budově. Muzeum založili v roce 2016 dvojčata Alban a Attila Scheiberovi; po ničivém požáru v lednu 2021 bylo znovu postaveno. Součástí komplexu je i restaurace a mýtná stanice pro silnici Timmelsjoch – ideální zastávka pro každého fanouška motorek.', 46.867, 11.024, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_am_Timmelsjoch.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_am_Timmelsjoch.jpg"}'::text[], 3),
    (v_route, 'Moso in Passiria / Moos in Passeier', 'Moos in Passeier (italsky Moso in Passiria) je horská obec v jihotyrolském údolí Passeier a představuje cíl trasy na italské straně průsmyku. Leží ve výšce 1 036 m n. m. na soutoku potoků Plan a Passirio. Po sjezdu plném serpentin je to příjemné místo k odpočinku a ochutnávce jihotyrolské kuchyně.', 46.79436, 11.08807, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Riva del Garda', 'Malebné městečko na severním cípu jezera obklopené strmými skalními stěnami je ideálním startem i cílem okruhu. Nabízí živou promenádu, středověkou věž Apponale a spoustu kaváren, kde si motorkáři odpočinou před nebo po jízdě. Díky poloze v Trentinu tu potkáte alpskou atmosféru snoubící se s jižní pohodou.', 45.88577, 10.84117, 'https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20014.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20014.JPG"}'::text[], 0),
    (v_route, 'Limone sul Garda', 'Klenot západního břehu na silnici Gardesana Occidentale, proslulý úzkými uličkami, citrusovými zahradami a řadou tunelů vytesaných do skály nad hladinou. Jízda sem patří k nejfotogeničtějším úsekům celého okruhu. Zastavte se v přístavu a vychutnejte si výhled na jezero i okolní hory.', 45.81468, 10.79322, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG"}'::text[], 1),
    (v_route, 'Malcesine', 'Půvabné městečko na východním břehu s dominantním hradem Scaligero tyčícím se nad jezerem. Odtud vede lanovka na vrchol Monte Baldo (1760 m) s panoramatem celého Garda a Dolomit. Klikaté uličky a přístav lákají k zastávce a doplnění sil.', 45.76442, 10.81024, 'https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG"}'::text[], 2),
    (v_route, 'Torbole / Ponale', 'Větrné městečko Torbole na severovýchodě je rájem surfařů a bránou ke staré silnici Ponale, jednomu z nejslavnějších úseků nad jezerem. Původní vozovka vytesaná do skalní stěny dnes slouží cyklistům a turistům a nabízí neopakovatelné výhledy z výšky přímo na hladinu. Pro motorkáře je to nezapomenutelná zastávka s panoramatem severního Garda.', 45.85271, 10.8812, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg"}'::text[], 3),
    (v_route, 'Sirmione', 'Úzký poloostrov na jižním konci jezera zakončený mohutným vodním hradem Scaligero z 13. století, obklopeným vodním příkopem. Kromě hradu tu najdete termální lázně a antické zbytky Grotte di Catullo. Historické centrum je pro motorky uzavřené, zaparkujte proto před vjezdem a projděte se pěšky.', 45.49744, 10.60507, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kranjska Gora', 'Známé horské středisko na severozápadě Slovinska a ideální startovní bod výjezdu na Vršič. V centru najdete kavárny, čerpací stanici i poslední možnost doplnit palivo před průsmykem. Odtud začíná řada 50 očíslovaných serpentin – motorkářský ráj Julských Alp.', 46.485, 13.786, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg"}'::text[], 0),
    (v_route, 'Jezero Jasna', 'Idylické tyrkysové jezero hned na úpatí průsmyku, se sochou kozoroha Zlatoroga a zrcadlícími se vrcholky Julských Alp. Ideální první zastávka na fotku hned po pár kilometrech jízdy z Kranjské Gory. Kolem vede pěší okruh a je tu i parkoviště pro motorky.', 46.469, 13.788, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg"}'::text[], 1),
    (v_route, 'Průsmyk Vršič (1611 m)', 'Nejvyšší silniční průsmyk ve Slovinsku a vrchol celé trasy s dechberoucími výhledy na okolní štíty. Na vrcholu je horská chata, parkoviště a startovní bod krátkých túr. Východní sjezd tvoří původní dlážděné serpentiny, které jsou za mokra zrádné – jeďte opatrně.', 46.433, 13.747, 'https://commons.wikimedia.org/wiki/Special:FilePath/Milky_Way_above_Vrsic_mountain_pass_in_Julian_Alps_in_Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Milky_Way_above_Vrsic_mountain_pass_in_Julian_Alps_in_Slovenia.jpg"}'::text[], 2),
    (v_route, 'Pramen Soči (Izvir Soče)', 'Pramen smaragdové řeky Soči v divokém údolí Trenta, kam se dostanete krátkou strmou stezkou od silnice. Křišťálově čistá voda vyvěrá přímo ze skalní stěny a je startem 138 km dlouhého toku řeky. Skvělá zastávka na oddech po sjezdu z průsmyku.', 46.409, 13.719, 'https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg"}'::text[], 3),
    (v_route, 'Bovec', 'Adrenalinové městečko v srdci údolí Soči a cíl celé trasy pod masivem Kaninu. Nabízí rafting, kavárny, restaurace i ubytování a je výborným místem na přenocování nebo doplnění paliva. Odtud lze pokračovat dál údolím Soči nebo se vrátit stejnou trasou.', 46.338, 13.552, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Brdo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Brdo.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Opatija / Rijeka – začátek Jadranské magistrály', 'Lázeňská Opatija u Rijeky je tradičním startem chorvatské Jadranské magistrály. Elegantní promenáda Lungomare a výhledy na Kvarnerský záliv jsou ideálním místem na natankování před cestou na jih. Odtud se silnice D8 vydává podél pobřeží pryč od dálnice A1.', 45.339, 14.306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG"}'::text[], 0),
    (v_route, 'Senj – pevnost Nehaj', 'Nad městem Senj se tyčí mohutná pevnost Nehaj z 16. století, symbol obávaných uskoků. Z jejích hradeb je nádherný rozhled na moře i na hřebeny Velebitu. Senj je zároveň známý jako největrnější místo pobřeží – právě zde často udeří bóra.', 44.99, 14.903, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG"}'::text[], 1),
    (v_route, 'Karlobag pod Velebitem', 'Malebné městečko Karlobag leží sevřené mezi mořem a strmými svahy Velebitu. Je to skvělá zastávka na kávu s výhledem na ostrov Pag přímo naproti přístavu. Úsek magistrály tudy vede v efektních zatáčkách nad útesy.', 44.529, 15.078, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG"}'::text[], 2),
    (v_route, 'Národní park Paklenica', 'Národní park Paklenica ukrývá dramatické kaňony Velika a Mala Paklenica zaříznuté do jižního Velebitu. Vstup leží jen kousek od magistrály u obce Starigrad a láká na krátkou procházku do hlubokých skalních soutěsek. Je to oblíbený ráj horolezců i příjemný stín po horké jízdě.', 44.283, 15.463, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG"}'::text[], 3),
    (v_route, 'Zadar – staré město a mořské varhany', 'Historické jádro Zadaru na poloostrově nabízí římské fórum, úzké uličky a slavné mořské varhany (Morske orgulje), které hrají tóny poháněné vlnami. Vedle nich instalace Pozdrav Slunci vytváří po setmění světelnou show. Zadar je krásným cílem coastalní etapy Jadranské magistrály.', 44.116, 15.226, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Přehrada Vidraru (Lacul Vidraru)', 'Mohutná obloukovitá přehrada z roku 1966 zadržuje jezero Vidraru sevřené v horách Fagaraš. Na hrázi vysoké přes 160 metrů stojí socha Prométhea a otevírá se odtud dech beroucí výhled na jižní část Transfăgărășanu. Ideální první zastávka na motorce, kde si dáte pauzu a vychutnáte panorama.', 45.363, 24.634, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG"}'::text[], 0),
    (v_route, 'Hrad Poenari (Drákulův hrad)', 'Zřícenina pevnosti Poenari trůní vysoko na skalním ostrohu nad údolím řeky Arges a je spojována s vládcem Vladem Napichovačem, předobrazem hraběte Drákuly. K hradu vede přes 1400 schodů, odměnou je ale úchvatný výhled do kraje. Pro milovníky historie a legend nezapomenutelná odbočka hned na začátku trasy.', 45.352, 24.635, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poenari%20Castle%20in%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poenari%20Castle%20in%20Romania.jpg"}'::text[], 1),
    (v_route, 'Jezero Bâlea (Bâlea Lac)', 'Ledovcové jezero Bâlea leží ve výšce 2034 metrů přímo v srdci nejvyšší části Transfăgărășanu. Kolem se rozkládají skalnaté štíty a horské louky, u břehu stojí chata i restaurace – dokonalé místo na zastávku a fotku motorky s alpskou kulisou. V zimě zde dokonce staví ledový hotel.', 45.604, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg"}'::text[], 2),
    (v_route, 'Vodopád Bâlea (Cascada Bâlea)', 'Nejvyšší vodopád v pohoří Fagaraš padá z výšky kolem 60 metrů po skalní stěně pod jezerem Bâlea. Nachází se na severní straně silnice a k jeho úpatí se dostanete krátkou procházkou nebo lanovkou. Skvělá zastávka na osvěžení uprostřed serpentin.', 45.618, 24.622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg"}'::text[], 3),
    (v_route, 'Tunel Bâlea', 'Tunel Bâlea dlouhý 887 metrů je nejvyšší silniční tunel v Rumunsku a označuje nejvyšší bod celé trasy pod hřebenem Fagaraše. Je nasvícený jen slabě, uvnitř bývá chladno a vlhko, proto dbejte zvýšené opatrnosti. Za jižním portálem vás čeká legendární výhled na kaskádu serpentin klesajících do údolí.', 45.596, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Furkapass', 'Furka je s výškou 2429 m nejvyšší z trojice průsmyků a spojuje kantony Uri a Wallis. Silnice plná dramatických vlásenek se proslavila i díky honičce z bondovky Goldfinger. Z vrcholu se otevírají velkolepé výhledy do údolí Rhôny.', 46.572, 8.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG"}'::text[], 0),
    (v_route, 'Ledovec Rhône a Belvédère', 'Přímo u serpentin na západní straně Furky leží ledovec Rhône, pramen řeky Rhôny, s legendární ledovou jeskyní vysekanou do jeho boku. Historický hotel Belvédère je ikonickým bodem trasy a ideálním místem na zastávku a fotky.', 46.573, 8.389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhoneglacier.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rhoneglacier.JPG"}'::text[], 1),
    (v_route, 'Grimselpass', 'Grimsel (2164 m) spojuje údolí Rhôny s Bernskou vysočinou a proslul soustavou přehradních jezer s tyrkysovou vodou. U vrcholu leží jezera Totensee a Grimselsee, obklopená holými žulovými skalami. Krajina působí drsně a měsíčně, což z průsmyku dělá nezapomenutelný zážitek.', 46.561, 8.333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg"}'::text[], 2),
    (v_route, 'Sustenpass', 'Susten (2224 m) je považován za nejlépe stavěnou z trojice silnic – široké, plynulé zatáčky s dokonalým výhledem na ledovec Stein. Průsmyk spojuje kantony Uri a Bern a nabízí jednu z nejplynulejších jízd v celém okruhu. Krátký tunel pod vrcholem odděluje obě strany hor.', 46.7267, 8.446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg"}'::text[], 3),
    (v_route, 'Andermatt', 'Andermatt je horské městečko v kantonu Uri, ideální výchozí i cílový bod celého okruhu. Leží na křižovatce alpských cest a nabízí ubytování, benzínky i restaurace před náročnou jízdou. Odtud se dá pokračovat i na další slavné průsmyky jako Oberalp či Gotthard.', 46.6353, 8.5941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Nockalmstraße – panoramatická silnice', 'Placená horská silnice dlouhá 34 km, která se klikatí 52 vlásenkami napříč jemně zaoblenými horami Nockberge. Pro motorkáře je to jeden z nejkrásnějších alpských zážitků – plynulé zatáčky, minimální provoz a nekonečné výhledy na travnaté kopce. Silnice je sjízdná od začátku května do konce října, mýto pro motorky je zhruba 18,50 €.', 46.885, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG"}'::text[], 0),
    (v_route, 'Innerkrems', 'Malebná horská osada ve výšce zhruba 1480 m tvoří severní vstupní bránu na Nockalmstraße. Je to ideální místo na natankování, kávu a poslední zastávku před výjezdem do serpentin. V okolí se rozkládá lyžařské a turistické středisko obklopené vrcholky Nockbergů.', 46.929, 13.688, 'https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems Krems in Kärnten 20070910a.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems Krems in Kärnten 20070910a.jpg"}'::text[], 1),
    (v_route, 'Eisentalhöhe – nejvyšší bod 2042 m', 'Nejvyšší bod celé Nockalmstraße ležící ve výšce 2042 m nad mořem. Z parkoviště se otevírá kruhový panoramatický výhled na hřebeny Nockbergů a v jasném počasí i na vzdálené vrcholy Vysokých Taur. Pro motorkáře je to povinná fotozastávka na střeše celé trasy.', 46.883, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse Eisentalhoehe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse Eisentalhoehe.JPG"}'::text[], 2),
    (v_route, 'Kölnbreinsperre – přehrada v údolí Maltatal', 'Impozantní klenbová přehrada vysoká 200 m je nejvyšší přehradou Rakouska a leží na konci úchvatné Malta Hochalmstraße plné tunelů a serpentin. Za tyrkysovou hladinou vodní nádrže se tyčí ledovcové štíty národního parku Vysoké Taury. Na koruně přehrady čeká vyhlídková plošina Airwalk a horský hotel s panoramatickou restaurací.', 47.078, 13.352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kölnbreinsperre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kölnbreinsperre.jpg"}'::text[], 3),
    (v_route, 'Millstätter See', 'Druhé největší korutanské jezero a nejobjemnější svého druhu s hloubkou až 142 m. Teplá tyrkysová voda a klidné pobřeží z něj dělají ideální místo na oddech, koupání a kávu před nebo po náročné jízdě horami. Okolní silnice kolem jezera nabízejí příjemnou vyjížďku bez dálnic.', 46.7903, 13.5745, 'https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt am Millstaetter See und Reißeck 08112015 8850.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt am Millstaetter See und Reißeck 08112015 8850.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Baden-Baden', 'Elegantní lázeňské město na severním okraji Černého lesa a startovní bod Schwarzwaldhochstraße. Reprezentativní kolonáda Trinkhalle a Kurhaus dávají tušit dávnou noblesu evropské smetánky. Ideální místo na kávu a natankování před stoupáním do hor.', 48.761, 8.241, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg"}'::text[], 0),
    (v_route, 'Mummelsee', 'Malebné ledovcové horské jezero ve výšce přes 1000 m přímo u silnice B500 pod vrcholem Hornisgrinde. Opředené pověstí o vodních vílách, s horským hotelem a stánky – oblíbená motorkářská zastávka. Skvělé místo na fotku i krátký odpočinek s výhledem na hladinu jezera.', 48.593, 8.207, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzwaldhochstrasse_Mummelsee.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzwaldhochstrasse_Mummelsee.JPG"}'::text[], 1),
    (v_route, 'Ruhestein', 'Horské sedlo a vstupní brána do Národního parku Černý les s návštěvnickým centrem a hospodou Ruhestein-Schänke. Křižovatka turistických tras nad divokým jezerem Wildsee. Příjemná zastávka na občerstvení uprostřed hřebenové jízdy.', 48.56, 8.22, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baiersbronn_-_Ruhesteinstra%C3%9Fe_-_Ruhestein-Sch%C3%A4nke_02_ies.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baiersbronn_-_Ruhesteinstra%C3%9Fe_-_Ruhestein-Sch%C3%A4nke_02_ies.jpg"}'::text[], 2),
    (v_route, 'Schliffkopf', 'Jeden z nejvyšších bodů na trase (1055 m) s otevřenými vřesovišti a širokými výhledy do kraje. Vrchol leží v Národním parku Černý les a v okolí najdete horský hotel i vyhlídkové trasy. Za jasného počasí dohlédnete daleko přes zalesněné hřebeny.', 48.535, 8.216, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Schwarzwald.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Schwarzwald.JPG"}'::text[], 3),
    (v_route, 'Freudenstadt', 'Cílové město trasy proslulé největším tržním náměstím v Německu, obklopeným podloubími a měšťanskými domy. Ideální místo na oběd a odpočinek po projetí hřebenovky. Odtud se dá pohodlně pokračovat dál do jižního Černého lesa.', 48.463, 8.411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt_-_Marktplatz_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt_-_Marktplatz_Kirche.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Postojnská jeskyně', 'Jedna z největších přístupných krasových jeskyní na světě, jejíž prohlídka začíná svezením podzemním elektrickým vláčkem. V rozlehlých síních uvidíte tisíce krápníků, stalagmitů a bílý sloup Brilliant. Skvělá zastávka za každého počasí – v jeskyni je stálých zhruba 10 °C.', 45.78127, 14.20571, 'https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20Cave%20-%20Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20Cave%20-%20Slovenia.jpg"}'::text[], 0),
    (v_route, 'Hrad Predjama', 'Renesanční hrad zasazený přímo do ústí jeskyně ve svislé skalní stěně, jeden z nejmalebnějších hradů Evropy. Proslul legendou o loupeživém rytíři Erazimu Predjamském, který odsud dlouho odolával obléhání. Pod hradem se rozkládá rozsáhlý jeskynní systém přístupný v teplejších měsících.', 45.8092, 14.1227, 'https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG"}'::text[], 1),
    (v_route, 'Škocjanské jeskyně', 'Součást seznamu UNESCO a jeden z nejvelkolepějších podzemních kaňonů na světě, vytesaný řekou Rekou. Trasa vede přes závratný most nad hlubokou soutěskou v obří Martelově síni. Návštěva je zážitkem po celý rok a doplní ji krásná krasová krajina kolem.', 45.66317, 13.98932, 'https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG"}'::text[], 2),
    (v_route, 'Lipica', 'Nejstarší a největší hřebčín ušlechtilých bílých lipicánů na světě, založený už roku 1580. Můžete si prohlédnout stáje, pastviny s desítkami koní i ukázky drezúry. Areál leží uprostřed typické krasové krajiny blízko italských hranic.', 45.66737, 13.88005, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg"}'::text[], 3),
    (v_route, 'Cerknické jezero', 'Největší občasné (mizející) jezero v Evropě, které se přes rok plní a znovu vysychá skrze podzemní krasové kanály. Podle ročního období tu najdete rozlehlou vodní plochu s ptactvem, nebo suchou louku. Okolní silnice jsou ideální pro klidnou vyjížďku krasovou planinou.', 45.75028, 14.36389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg"}'::text[], 4);
